/**
 * src/lib/brandProgram.js
 * ─────────────────────────────────────────────────────────────────────────────
 * "Create Your Own Brand" — a paid TRAINING & SIMULATION experience. PURE
 * configuration rules (no DB, no I/O).
 *
 * The participant buys access to a brand simulator: they pick 3–4 products from
 * the catalogue the admin opened to the program, name their fictional brand and
 * choose a package; once the payment is verified, their dashboard shows
 * SIMULATED training data (orders and statuses generated by brandSimulation.js).
 * Catalogue products are only READ (name + image snapshot): nothing in this
 * program is a real order, stock movement, customer, sale or earning, and
 * nothing is ever credited to the wallet.
 *
 * Nothing commercial is hardcoded: the program and the simulation ship DISABLED
 * with no package and no simulation setting. Refund terms are written and
 * published by an administrator; none ship with the code.
 * ─────────────────────────────────────────────────────────────────────────────
 */

import { PERCENT_BASES, PERCENT_KEYS, MONEY_BASES, missingPricingFields, packageBreakdown } from './brandPricing.js';

export const BRAND_SETTING_ID = 'brand-program-config';
export const BRAND_TERMS_SETTING_ID = 'brand-refund-terms';

export const BRAND_LIMITS = Object.freeze({
  MAX_PACKAGES:                 30,
  MAX_PRICE:                    10_000_000,
  MAX_FEATURES:                 20,
  FEATURE_MAX:                  160,
  MAX_BRANDING_OPTIONS:         50,
  NAME_MIN:                     2,
  NAME_MAX:                     80,
  DESCRIPTION_MAX:              1000,
  NOTES_MAX:                    500,
  TERMS_MAX:                    20_000,
  SORT_MAX:                     10_000,
  BRAND_NAME_MIN:               2,
  BRAND_NAME_MAX:               40,
  MAX_START_DELAY_HOURS:        24 * 365,
  MAX_DAILY_VOLUME:             1000,
  MAX_CONFIRMATION_DELAY_HOURS: 24 * 30,
  MAX_DELIVERY_DELAY_HOURS:     24 * 90,
  MAX_CATALOG_PRODUCTS:         200,
  MIN_SELECTED_PRODUCTS:        3,
  MAX_SELECTED_PRODUCTS:        4,
});

/** Final outcomes of a simulated order — the admin distribution covers exactly these. */
export const SIM_OUTCOMES = Object.freeze(['delivered', 'refused', 'returned', 'noResponse', 'cancelled']);
/** Every status a simulated order can display (pending and confirmed are intermediate). */
export const SIM_STATUSES = Object.freeze(['pending', 'confirmed', ...SIM_OUTCOMES]);

const ID_RE = /^[a-z0-9][a-z0-9_-]{0,39}$/;
const REQUEST_ID_RE = /^[A-Za-z0-9_-]{8,100}$/;
/** Store product ids (Prisma uuid); kept loose but safe: no spaces, no markup. */
const PRODUCT_ID_RE = /^[A-Za-z0-9_-]{1,64}$/;

// ── Small coercions ───────────────────────────────────────────────────────────

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

function cleanText(v, max) {
  return String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function cleanMultiline(v, max) {
  return String(v ?? '').replace(/\r\n?/g, '\n').replace(/[ \t]+\n/g, '\n').trim().slice(0, max);
}

/** Finite number from a number or numeric string, else NaN. */
function toNum(v) {
  if (typeof v === 'number') return v;
  if (typeof v === 'string' && v.trim() !== '') return Number(v);
  return NaN;
}

const round2 = (n) => Math.round(n * 100) / 100;

/** null/'' → null; a number in [min, max] → rounded to 2 dp; anything else → NaN. */
function optionalAmount(v, min, max) {
  if (v === null || v === undefined || v === '') return null;
  const n = toNum(v);
  return Number.isFinite(n) && n >= min && n <= max ? round2(n) : NaN;
}

/** null/'' → null; a percentage in [0, 100] with ≤ 2 decimals → itself; anything else → NaN. */
function optionalPercent(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = toNum(v);
  return Number.isFinite(n) && n >= 0 && n <= 100 && Math.abs(n * 100 - Math.round(n * 100)) < 1e-6 ? round2(n) : NaN;
}

/** null/'' → null; an integer in [min, max] → itself; anything else → NaN. */
function optionalInt(v, min, max) {
  if (v === null || v === undefined || v === '') return null;
  const n = toNum(v);
  return Number.isSafeInteger(n) && n >= min && n <= max ? n : NaN;
}

const toBool = (v) => v === true;
const isoOrNull = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

/** Unique, cleaned, non-empty strings (order kept), capped. */
function cleanList(v, max, itemMax) {
  const out = [];
  const seen = new Set();
  for (const raw of Array.isArray(v) ? v : []) {
    const s = cleanText(raw, itemMax);
    const key = s.toLowerCase();
    if (!s || seen.has(key)) continue;
    seen.add(key);
    out.push(s);
    if (out.length >= max) break;
  }
  return out;
}

// ── Package / branding option ─────────────────────────────────────────────────

/** Unique valid product ids (order kept); `bad` set when an entry is malformed. */
function productIdList(raw, max) {
  const ids = [];
  let bad = !Array.isArray(raw) && raw !== undefined && raw !== null;
  for (const v of Array.isArray(raw) ? raw.slice(0, max) : []) {
    const id = typeof v === 'string' ? v.trim() : '';
    if (!PRODUCT_ID_RE.test(id)) { bad = true; continue; }
    if (!ids.includes(id)) ids.push(id);
  }
  return { ids, bad, tooMany: Array.isArray(raw) && raw.length > max };
}

/**
 * Normalize + validate one package. `errors` maps a field to an error code.
 * Commercial fields may stay empty while the package is INACTIVE (draft);
 * an ACTIVE package needs every one of them (see brandPricing.missingPricingFields).
 */
function normalizePackage(src) {
  const p = isObj(src) ? src : {};
  const L = BRAND_LIMITS;
  const errors = {};

  const id = String(p.id ?? '').trim();
  if (!ID_RE.test(id)) errors.id = 'INVALID_ID';
  const name = cleanText(p.name, L.NAME_MAX);
  if (name.length < L.NAME_MIN) errors.name = 'INVALID_NAME';
  const price = optionalAmount(p.price, 0.01, L.MAX_PRICE);
  if (price === null || Number.isNaN(price)) errors.price = 'INVALID_PRICE';
  const sortOrder = optionalInt(p.sortOrder ?? 0, -L.SORT_MAX, L.SORT_MAX);
  if (Number.isNaN(sortOrder)) errors.sortOrder = 'INVALID_NUMBER';
  if (Array.isArray(p.features) && p.features.length > L.MAX_FEATURES) errors.features = 'TOO_MANY_FEATURES';

  const amount = (key) => {
    const v = optionalAmount(p[key], 0, L.MAX_PRICE);
    if (Number.isNaN(v)) errors[key] = 'INVALID_AMOUNT';
    return Number.isNaN(v) ? null : v;
  };
  const deliveryCost = amount('deliveryCost');
  const logisticsCost = amount('logisticsCost');
  const vatPercent = optionalPercent(p.vatPercent);
  if (Number.isNaN(vatPercent)) errors.vatPercent = 'INVALID_PERCENT';
  const productCount = optionalInt(p.productCount, L.MIN_SELECTED_PRODUCTS, L.MAX_SELECTED_PRODUCTS);
  if (Number.isNaN(productCount)) errors.productCount = 'INVALID_PRODUCT_COUNT';
  const list = productIdList(p.productIds, L.MAX_CATALOG_PRODUCTS);
  if (list.bad) errors.productIds = 'INVALID_PRODUCT_ID';
  if (list.tooMany) errors.productIds = 'TOO_MANY_PRODUCTS';

  const srcPct = isObj(p.percentages) ? p.percentages : {};
  const percentages = {};
  for (const k of PERCENT_KEYS) {
    const e = isObj(srcPct[k]) ? srcPct[k] : {};
    const value = optionalPercent(e.value);
    if (Number.isNaN(value)) errors[`percentages.${k}.value`] = 'INVALID_PERCENT';
    const base = e.base === undefined || e.base === null || e.base === '' ? null : String(e.base);
    if (base !== null && !Object.values(PERCENT_BASES).includes(base)) errors[`percentages.${k}.base`] = 'INVALID_BASE';
    percentages[k] = { value: Number.isNaN(value) ? null : value, base: errors[`percentages.${k}.base`] ? null : base };
  }

  const value = {
    id,
    name,
    description: cleanMultiline(p.description, L.DESCRIPTION_MAX),
    price: Number.isNaN(price) ? null : price,
    features: cleanList(p.features, L.MAX_FEATURES, L.FEATURE_MAX),
    active: toBool(p.active),
    sortOrder: Number.isNaN(sortOrder) || sortOrder === null ? 0 : sortOrder,
    productCount: Number.isNaN(productCount) ? null : productCount,
    productIds: list.ids,
    deliveryCost,
    logisticsCost,
    vatPercent: Number.isNaN(vatPercent) ? null : vatPercent,
    percentages,
  };

  // Shares applied to the same money base cannot exceed 100 % of it.
  for (const base of MONEY_BASES) {
    const sum = PERCENT_KEYS.filter((k) => percentages[k].base === base && percentages[k].value !== null)
      .reduce((a, k) => a + percentages[k].value, 0);
    if (sum > 100) errors.percentages = 'PERCENT_SUM_OVER_100';
  }

  if (value.active) {
    for (const f of missingPricingFields(value)) if (!errors[f]) errors[f] = 'REQUIRED_WHEN_ACTIVE';
    if (value.productCount !== null && list.ids.length < value.productCount && !errors.productIds) errors.productIds = 'NOT_ENOUGH_PRODUCTS';
  }
  return { value, errors };
}

function normalizeBrandingOption(src) {
  const o = isObj(src) ? src : {};
  const errors = {};
  const id = String(o.id ?? '').trim();
  if (!ID_RE.test(id)) errors.id = 'INVALID_ID';
  const label = cleanText(o.label, BRAND_LIMITS.NAME_MAX);
  if (label.length < BRAND_LIMITS.NAME_MIN) errors.label = 'INVALID_NAME';
  return {
    value: { id, label, description: cleanMultiline(o.description, BRAND_LIMITS.NOTES_MAX), active: toBool(o.active) },
    errors,
  };
}

// ── Simulation settings ───────────────────────────────────────────────────────

/**
 * Simulation settings. While `enabled` is false any field may stay empty; turning
 * it on requires every value (start delay, daily volume range, the two delays
 * that set the speed, and an outcome distribution summing to exactly 100 %).
 * `activeSince` is service-managed (last off→on switch) and never read from input.
 */
function normalizeSimulation(src, errors) {
  const s = isObj(src) ? src : {};
  const L = BRAND_LIMITS;
  const field = (key, min, max) => {
    const v = optionalInt(s[key], min, max);
    if (Number.isNaN(v)) errors[`simulation.${key}`] = 'INVALID_NUMBER';
    return Number.isNaN(v) ? null : v;
  };
  if (has(s, 'enabled') && typeof s.enabled !== 'boolean') errors['simulation.enabled'] = 'INVALID_BOOLEAN';

  const value = {
    enabled: s.enabled === true,
    startDelayHours:        field('startDelayHours', 0, L.MAX_START_DELAY_HOURS),
    dailyVolumeMin:         field('dailyVolumeMin', 0, L.MAX_DAILY_VOLUME),
    dailyVolumeMax:         field('dailyVolumeMax', 0, L.MAX_DAILY_VOLUME),
    confirmationDelayHours: field('confirmationDelayHours', 0, L.MAX_CONFIRMATION_DELAY_HOURS),
    deliveryDelayHours:     field('deliveryDelayHours', 0, L.MAX_DELIVERY_DELAY_HOURS),
    distribution: {},
    activeSince: null,
  };
  const dist = isObj(s.distribution) ? s.distribution : {};
  for (const k of SIM_OUTCOMES) {
    const v = optionalInt(dist[k], 0, 100);
    if (Number.isNaN(v)) errors[`simulation.distribution.${k}`] = 'INVALID_PERCENT';
    value.distribution[k] = Number.isNaN(v) ? null : v;
  }

  const { dailyVolumeMin: min, dailyVolumeMax: max, confirmationDelayHours: conf, deliveryDelayHours: del } = value;
  if (min !== null && max !== null && min > max) errors['simulation.dailyVolumeMax'] = 'MAX_BELOW_MIN';
  if (conf !== null && del !== null && del < conf) errors['simulation.deliveryDelayHours'] = 'DELIVERY_BEFORE_CONFIRMATION';

  if (value.enabled) {
    for (const key of ['startDelayHours', 'dailyVolumeMin', 'dailyVolumeMax', 'confirmationDelayHours', 'deliveryDelayHours']) {
      if (value[key] === null && !errors[`simulation.${key}`]) errors[`simulation.${key}`] = 'REQUIRED_WHEN_ENABLED';
    }
    if (max !== null && max < 1 && !errors['simulation.dailyVolumeMax']) errors['simulation.dailyVolumeMax'] = 'VOLUME_REQUIRED';
    const parts = SIM_OUTCOMES.map((k) => value.distribution[k]);
    if (parts.some((v) => v === null)) errors['simulation.distribution'] = errors['simulation.distribution'] || 'REQUIRED_WHEN_ENABLED';
    else if (parts.reduce((a, b) => a + b, 0) !== 100) errors['simulation.distribution'] = 'DISTRIBUTION_NOT_100';
  }
  return value;
}

/** Every value the engine needs is present (the save validation guarantees it while enabled). */
export function isSimulationRunnable(sim) {
  if (!sim || !sim.enabled) return false;
  const nums = [sim.startDelayHours, sim.dailyVolumeMin, sim.dailyVolumeMax, sim.confirmationDelayHours, sim.deliveryDelayHours];
  if (nums.some((n) => !Number.isSafeInteger(n) || n < 0)) return false;
  if (sim.dailyVolumeMin > sim.dailyVolumeMax || sim.deliveryDelayHours < sim.confirmationDelayHours) return false;
  const parts = SIM_OUTCOMES.map((k) => sim.distribution?.[k]);
  return parts.every((v) => Number.isSafeInteger(v) && v >= 0) && parts.reduce((a, b) => a + b, 0) === 100;
}

// ── Whole config ──────────────────────────────────────────────────────────────

/**
 * Validate a full config submitted by the admin. Returns { ok, errors, value }:
 * `errors` maps a path (e.g. "packages.0.price") to an error code.
 */
export function validateBrandConfig(input) {
  const src = isObj(input) ? input : {};
  const L = BRAND_LIMITS;
  const errors = {};

  if (has(src, 'enabled') && typeof src.enabled !== 'boolean') errors.enabled = 'INVALID_BOOLEAN';

  // Catalogue (pool of store products the packages draw from): ids only; names,
  // images and availability are always read live.
  const rawCatalog = src.catalogProductIds === undefined ? [] : src.catalogProductIds;
  const catalogProductIds = [];
  if (!Array.isArray(rawCatalog)) errors.catalogProductIds = 'INVALID_LIST';
  else {
    if (rawCatalog.length > L.MAX_CATALOG_PRODUCTS) errors.catalogProductIds = 'TOO_MANY_PRODUCTS';
    for (const raw of rawCatalog.slice(0, L.MAX_CATALOG_PRODUCTS)) {
      const id = typeof raw === 'string' ? raw.trim() : '';
      if (!PRODUCT_ID_RE.test(id)) { errors.catalogProductIds = 'INVALID_PRODUCT_ID'; continue; }
      if (!catalogProductIds.includes(id)) catalogProductIds.push(id);
    }
  }
  const inPool = new Set(catalogProductIds);

  const rawPackages = Array.isArray(src.packages) ? src.packages : [];
  if (rawPackages.length > L.MAX_PACKAGES) errors.packages = 'TOO_MANY_PACKAGES';
  const packages = [];
  const seenPkg = new Set();
  rawPackages.slice(0, L.MAX_PACKAGES).forEach((raw, i) => {
    const { value, errors: e } = normalizePackage(raw);
    for (const [k, code] of Object.entries(e)) errors[`packages.${i}.${k}`] = code;
    if (value.id && seenPkg.has(value.id)) errors[`packages.${i}.id`] = 'DUPLICATE_ID';
    if (value.productIds.some((pid) => !inPool.has(pid)) && !errors[`packages.${i}.productIds`]) errors[`packages.${i}.productIds`] = 'PRODUCT_NOT_IN_CATALOGUE';
    seenPkg.add(value.id);
    packages.push(value);
  });

  const rawOptions = Array.isArray(src.brandingOptions) ? src.brandingOptions : [];
  if (rawOptions.length > L.MAX_BRANDING_OPTIONS) errors.brandingOptions = 'TOO_MANY_OPTIONS';
  const brandingOptions = [];
  const seenOpt = new Set();
  rawOptions.slice(0, L.MAX_BRANDING_OPTIONS).forEach((raw, i) => {
    const { value, errors: e } = normalizeBrandingOption(raw);
    for (const [k, code] of Object.entries(e)) errors[`brandingOptions.${i}.${k}`] = code;
    if (value.id && seenOpt.has(value.id)) errors[`brandingOptions.${i}.id`] = 'DUPLICATE_ID';
    seenOpt.add(value.id);
    brandingOptions.push(value);
  });

  const simulation = normalizeSimulation(src.simulation, errors);

  return {
    ok: Object.keys(errors).length === 0,
    errors,
    value: { enabled: src.enabled === true, packages, brandingOptions, simulation, catalogProductIds },
  };
}

/**
 * Read a STORED config (never throws). Saves are validated strictly, so stored
 * data is normally valid; anything unreadable degrades to "not configured".
 */
export function normalizeBrandConfig(raw) {
  const r = isObj(raw) ? raw : {};
  const { value } = validateBrandConfig(r);
  value.simulation.activeSince = isoOrNull(isObj(r.simulation) ? r.simulation.activeSince : null);
  return {
    ...value,
    updatedAt: typeof r.updatedAt === 'string' ? r.updatedAt : null,
    updatedBy: typeof r.updatedBy === 'string' ? r.updatedBy : null,
  };
}

/** A package an affiliate may buy: active and every commercial field configured (products checked live). */
export function isPublishablePackage(p) {
  return !!(p && p.active && ID_RE.test(p.id || '') && p.name && p.price > 0 && packageBreakdown(p));
}

/** The package's eligible products right now, in the admin's order (`catalog` = eligibleCatalog output). */
export function packageProducts(pkg, catalog) {
  const byId = new Map((catalog || []).map((c) => [c.id, c]));
  return (pkg?.productIds || []).map((id) => byId.get(id)).filter(Boolean);
}

/** Offered = publishable AND enough eligible products to pick exactly `productCount`. */
export function isOfferedPackage(pkg, catalog) {
  return isPublishablePackage(pkg) && packageProducts(pkg, catalog).length >= pkg.productCount;
}

/** What an affiliate sees (and what a request snapshots) of an offered package. */
export function publicPackage(pkg, catalog) {
  const { id, name, description, price, features, productCount } = pkg;
  return { id, name, description, price, features, productCount, products: packageProducts(pkg, catalog), breakdown: packageBreakdown(pkg) };
}

/**
 * The offer an affiliate may see. Disabled program → `{ enabled: false }` only.
 * Inactive / incomplete packages, packages without enough eligible products,
 * inactive options, simulation settings and audit stamps are never sent.
 * `catalog` = the eligible catalogue products (see eligibleCatalog), passed in by the caller.
 */
export function publicBrandOffer(config, catalog = []) {
  const c = config || normalizeBrandConfig(null);
  if (!c.enabled) return { enabled: false };
  return {
    enabled: true,
    packages: c.packages
      .filter((p) => isOfferedPackage(p, catalog))
      .sort((a, b) => (a.sortOrder - b.sortOrder) || (a.price - b.price))
      .map((p) => publicPackage(p, catalog)),
    brandingOptions: c.brandingOptions.filter((o) => o.active).map(({ id, label, description }) => ({ id, label, description })),
  };
}

// ── Catalogue products ────────────────────────────────────────────────────────

/** Columns read from the store Product table — never prices, stock, costs or suppliers. */
export const CATALOG_PRODUCT_SELECT = Object.freeze({ id: true, title: true, images: true, status: true, isActive: true, isLocked: true });

/** A store product may be offered: published (status Active), active and not locked by the admin. */
export function isEligibleProduct(p) {
  return !!(p && PRODUCT_ID_RE.test(p.id || '') && p.status === 'Active' && p.isActive === true && p.isLocked !== true && cleanText(p.title, 200));
}

function firstImage(images) {
  const first = Array.isArray(images) ? images[0] : null;
  const url = typeof first === 'string' ? first : (isObj(first) ? (first.url || first.src || '') : '');
  return typeof url === 'string' && /^(https?:\/\/|\/)[^\s"'<>]*$/.test(url) ? url.slice(0, 1000) : null;
}

/** What is shown and snapshotted for a catalogue product: id, name, first image. */
export function catalogProductView(p) {
  return { id: p.id, title: cleanText(p.title, 200), image: firstImage(p.images) };
}

/**
 * The offerable catalogue, in the admin's order: catalogue ids whose product
 * exists and is eligible right now. `products` = rows read with CATALOG_PRODUCT_SELECT.
 */
export function eligibleCatalog(config, products) {
  const byId = new Map((products || []).map((p) => [p.id, p]));
  return (config?.catalogProductIds || []).map((id) => byId.get(id)).filter(isEligibleProduct).map(catalogProductView);
}

/**
 * Participant's selection: unique ids, exactly MIN..MAX of them. Returns the ids
 * (input order, de-duplicated) or null. Eligibility is checked by the service.
 */
export function normalizeProductSelection(raw) {
  if (!Array.isArray(raw) || raw.length > 20) return null;
  const ids = [];
  for (const v of raw) {
    if (typeof v !== 'string' || !PRODUCT_ID_RE.test(v)) return null;
    if (ids.includes(v)) return null;
    ids.push(v);
  }
  return ids.length >= BRAND_LIMITS.MIN_SELECTED_PRODUCTS && ids.length <= BRAND_LIMITS.MAX_SELECTED_PRODUCTS ? ids : null;
}

/** Package ids present in `before` but missing from `after` (packages are deactivated, never removed). */
export function removedPackageIds(before, after) {
  const kept = new Set((after?.packages || []).map((p) => p.id));
  return (before?.packages || []).map((p) => p.id).filter((id) => id && !kept.has(id));
}

// ── Refund terms (written and approved by an administrator) ───────────────────

/** Stored terms: a draft the admin edits, and the last version an admin approved and published. */
export function normalizeRefundTerms(raw) {
  const r = isObj(raw) ? raw : {};
  const d = isObj(r.draft) ? r.draft : {};
  const p = isObj(r.published) ? r.published : null;
  const version = p ? optionalInt(p.version, 1, 1_000_000) : null;
  const text = p ? cleanMultiline(p.text, BRAND_LIMITS.TERMS_MAX) : '';
  return {
    draft: {
      text: cleanMultiline(d.text, BRAND_LIMITS.TERMS_MAX),
      updatedAt: isoOrNull(d.updatedAt),
      updatedBy: typeof d.updatedBy === 'string' ? d.updatedBy : null,
    },
    published: p && Number.isSafeInteger(version) && text
      ? { version, text, publishedAt: isoOrNull(p.publishedAt), publishedBy: typeof p.publishedBy === 'string' ? p.publishedBy : null }
      : null,
  };
}

export function validateTermsDraft(input) {
  const src = isObj(input) ? input : {};
  if (typeof src.text !== 'string') return { ok: false, errors: { text: 'INVALID_TEXT' }, value: null };
  if (src.text.length > BRAND_LIMITS.TERMS_MAX) return { ok: false, errors: { text: 'TERMS_TOO_LONG' }, value: null };
  return { ok: true, errors: {}, value: { text: cleanMultiline(src.text, BRAND_LIMITS.TERMS_MAX) } };
}

/** What an affiliate sees: only the published version, never the draft. */
export function publicRefundTerms(terms) {
  const p = terms?.published;
  return p ? { version: p.version, text: p.text, publishedAt: p.publishedAt } : null;
}

// ── Access request inputs ─────────────────────────────────────────────────────

/** Fictional brand name: 2–40 letters (any script), digits, spaces and ' & . - */
export function normalizeBrandName(raw) {
  const s = cleanText(raw, 200);
  if (s.length < BRAND_LIMITS.BRAND_NAME_MIN || s.length > BRAND_LIMITS.BRAND_NAME_MAX) return null;
  return /^[\p{L}\p{N}][\p{L}\p{N} '&.-]*$/u.test(s) ? s : null;
}

export const isValidClientRequestId = (v) => typeof v === 'string' && REQUEST_ID_RE.test(v);

/**
 * Transfer reference compared across payment proofs and deposits: upper-case,
 * without spaces or separators (- _ . / #). null when empty.
 */
export function normalizeTransferReference(v) {
  const s = String(v ?? '').toUpperCase().replace(/[\s\-_./#]+/g, '');
  return s ? s.slice(0, 120) : null;
}
